# 표시된 프로젝트의 결과물은 학습에 절대 안 들어가고, 상호작용 흔적만 쓴다
from dataclasses import dataclass
@dataclass
class Record:
    project: str
    kind: str      # 'artifact'(영상·이미지) 또는 'trace'(어떤 지시·수정·선택을 했나)
    payload: str
PROTECTED = {"studio_a/next_blockbuster"}
def training_view(records):
    out = []
    for r in records:
        if r.project in PROTECTED and r.kind == "artifact":
            continue                                     # 결과물은 영구 제외
        if r.kind == "trace":
            r = Record(r.project, r.kind, r.payload.split("|")[0])  # 내용은 빼고 행동만
        out.append(r)
    return out
recs = [Record("studio_a/next_blockbuster", "artifact", "shot_017.mp4"),
        Record("studio_a/next_blockbuster", "trace", "regenerate|헬멧 디자인 X"),
        Record("indie/demo", "artifact", "clip.mp4")]
for r in training_view(recs):
    print(r.project, r.kind, r.payload)

# 모델 여러 개를 줄줄이 잇는 파이프라인 — 넘겨줄 때마다 의도가 조금씩 샌다
def chain(success_per_hop, hops):
    return success_per_hop ** hops
for hops in (1, 3, 5, 8):
    print(f"{hops}번 넘김, 매번 95% 보존 → {chain(0.95, hops):.1%}, 90% → {chain(0.90, hops):.1%}")
# 반복(REPL) 루프: 한 번 시도 성공률 p, 스스로 보고 고칠 기회 k 번
def with_retries(p, k):
    return 1 - (1 - p) ** (k + 1)
print("한 번 60%, 스스로 고칠 기회 3번 →", f"{with_retries(0.6, 3):.1%}")

# 시도를 늘리면 히트가 나올 확률 — 넷플릭스 800편 대 대형 스튜디오 10편
def p_hit(n, p):
    return 1 - (1 - p) ** n
for n, budget in [(10, 500), (800, 30)]:
    print(f"{n:>4}편 × ${budget}M = ${n*budget/1000:.1f}B, "
          f"히트율 5%면 하나 이상 {p_hit(n, 0.05):.1%}, 기대 히트 {n*0.05:.1f}편")
# 창작자 한 명: 아이디어 하나 실행에 2주 → 하루에 20개를 시험할 수 있게 되면
for n in (1, 20):
    print(f"아이디어 {n}개 시험, 각 10% 성공 → 하나 이상 성공 {p_hit(n, 0.10):.1%}")
